-- PYTH BOMB: question bank, batch 5 — 110 EASY general-knowledge questions (Claude, 2026-10-16)
-- Run in Supabase SQL Editor AFTER 020. Safe to run more than once (duplicate question text is skipped).
-- Check the list in perguntas-lote5-para-conferir.txt first.
-- Step 1 also allows two new category names (animals, brands). No gameplay change.

alter table public.questions drop constraint if exists questions_category_check;
alter table public.questions add constraint questions_category_check
  check (category in ('pyth', 'community', 'general', 'sports', 'movies', 'fun', 'music', 'tv', 'geography', 'history', 'science', 'food', 'games', 'tech', 'animals', 'brands'));

on conflict do nothing;

-- check: how many batch-5 questions are in the bank now (should be 110)
select count(*) as batch5_questions from public.questions where source_reference = 'Claude batch 5 (easy)';
-- and the whole bank that the game can deal right now:
select count(*) as questions_in_play from public.questions where verified and active;
